<?php require __DIR__.'/_start.php';$shift=match($mode){'day'=>'1 day','week'=>'7 days','month'=>'1 month'}; ?>
<section class="customer-card"><div class="section-heading"><h2><?= e($start->format('d.m.Y').' – '.$end->modify('-1 day')->format('d.m.Y')) ?></h2></div><nav class="customer-tabs" aria-label="Takvim görünümü"><?php foreach(['day'=>'Günlük','week'=>'Haftalık','month'=>'Aylık']as$key=>$label): ?><a href="<?= e(url('employee/calendar?'.http_build_query(['mode'=>$key,'date'=>$date]))) ?>" class="<?= $mode===$key?'is-current':'' ?>"><?= e($label) ?></a><?php endforeach ?></nav><form method="get" action="<?= e(url('employee/calendar')) ?>" class="row g-3 align-items-end mt-2"><input type="hidden" name="mode" value="<?= e($mode) ?>"><div class="col-md-6"><label for="calendar-date">Takvim tarihi</label><input class="form-control" id="calendar-date" type="date" name="date" required value="<?= e($date) ?>"></div><div class="col-md-6"><button class="btn btn-outline-dark" type="submit">Görüntüle</button></div></form><div class="wizard-actions"><a class="btn btn-outline-dark" href="<?= e(url('employee/calendar?'.http_build_query(['mode'=>$mode,'date'=>$start->modify('-'.$shift)->format('Y-m-d')]))) ?>">← Önceki</a><a href="<?= e(url('employee/calendar?mode='.$mode)) ?>">Bugün</a><a class="btn btn-outline-dark" href="<?= e(url('employee/calendar?'.http_build_query(['mode'=>$mode,'date'=>$start->modify('+'.$shift)->format('Y-m-d')]))) ?>">Sonraki →</a></div>
<?php if($mode==='month'): ?><div class="employee-month-grid"><?php foreach(['Pzt','Sal','Çar','Per','Cum','Cmt','Paz']as$label): ?><strong class="calendar-label"><?= e($label) ?></strong><?php endforeach ?><?php for($i=1;$i<(int)$start->format('N');$i++): ?><span aria-hidden="true"></span><?php endfor ?><?php foreach($days as$d): ?><a class="employee-month-day <?= $d['date']===date('Y-m-d')?'today':'' ?>" href="<?= e(url('employee/calendar?mode=day&date='.$d['date'])) ?>"><strong><?= (int)substr($d['date'],8,2) ?></strong><small><?= count($d['appointments']) ?> randevu</small><small><?= $d['leaves']?'İzin':($d['hours']?'Çalışma':'Kapalı') ?></small><?php if($d['breaks']): ?><small>Mola var</small><?php endif ?></a><?php endforeach ?></div><?php endif ?></section>
<?php if($mode!=='month'): ?><div class="employee-day-grid mt-4"><?php foreach($days as$plan): ?><section class="customer-card"><div class="section-heading"><h2><?= e(date('d.m.Y',strtotime($plan['date']))) ?><small class="d-block"><?= e($dayNames[(int)date('N',strtotime($plan['date']))]) ?></small></h2><?php if($mode==='week'): ?><a href="<?= e(url('employee/calendar?mode=day&date='.$plan['date'])) ?>">Gün</a><?php endif ?></div><?php require __DIR__.'/_plan.php'; ?><hr><?php $appointmentRows=$plan['appointments'];require __DIR__.'/_appointments.php'; ?></section><?php endforeach ?></div><?php endif ?>
<?php require __DIR__.'/_end.php'; ?>
